import React, { useState, useEffect } from 'react';
import { getProducts, deleteProduct, createTestProduct } from './api';
import './styles.css';

function App() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchAll = async () => {
    try {
      setLoading(true);
      const data = await getProducts();
      setProducts(data);
      setError(null);
    } catch (err) {
      setError(err.message || 'Ошибка загрузки');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, []);

  const handleDelete = async (id) => {
    await deleteProduct(id);
    fetchAll();
  };

  const handleAddTest = async () => {
    await createTestProduct();
    fetchAll();
  };

  return (
    <div className="container">
      <header>
        <h1>⚡ PC Parts Store (Rewrite)</h1>
        <button onClick={handleAddTest} className="btn-add">+ Добавить тест-товар</button>
      </header>

      {error && <div className="error">Ошибка: {error}</div>}
      
      {loading ? (
        <div className="loading">Загрузка товаров...</div>
      ) : (
        <div className="grid">
          {products.map(p => (
            <div key={p.id} className="card">
              <div className="card-header">
                <span className="category">{p.category}</span>
                <span className="price">{p.price.toLocaleString()} ₽</span>
              </div>
              <h3>{p.title}</h3>
              <p>{p.description}</p>
              <button onClick={() => handleDelete(p.id)} className="btn-delete">
                Удалить
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
